            "template_html": "<h2>Company & Website Information</h2><h2>Introduction</h2><p><span>This is the privacy policy for</span>&nbsp;<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"{{company_info_website_url}}\"><span class='f-text-highlight'>{{company_info_website_url}}</span></a></p><p>The responsible controller for the processing on this site is</p><p class='f-text-highlight'>{{company_info_company_name}}</p><p class='f-text-highlight'>{{company_info_company_address}}</p><p class='f-text-highlight'>{{company_info_email_address}}</p><p class='f-text-highlight'>{{company_info_phone_number}}</p><p class='f-text-highlight'>{{company_info_dpo_TEMPLATE}}</p>",
